  function contactDetail(){
    const c=state.contacts.find(x=>x.id===state.selectedContactId);if(!c){state.section='contacts';contacts();return;}
    const docs=state.documents.filter(d=>d.contact_id===c.id&&d.status==='posted');
    const tx=state.transactions.filter(t=>t.contact_id===c.id&&t.status==='posted');
    const sales=docs.filter(d=>['goods_sale','service_sale'].includes(d.document_type)).reduce((n,d)=>n+Number(d.total_amount||0),0);
    const purchases=docs.filter(d=>['purchase','service_purchase'].includes(d.document_type)).reduce((n,d)=>n+Number(d.total_amount||0),0);
    const received=tx.filter(t=>t.transaction_type==='customer_receipt').reduce((n,t)=>n+Number(t.amount||0),0);
    const paid=tx.filter(t=>['supplier_payment','creditor_payment'].includes(t.transaction_type)).reduce((n,t)=>n+Number(t.amount||0),0);
    const ledger=state.contactLedger.filter(x=>x.contact_id===c.id).sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date)));
    const balance=ledger.reduce((n,x)=>n+Number(x.debit||0)-Number(x.credit||0),0);
    const ledgerRows=ledger.slice(0,60).map(x=>'<tr><td>'+dateFa(x.entry_date)+'</td><td>'+esc(x.description||x.entry_type||'—')+'</td><td>'+money(x.debit)+'</td><td>'+money(x.credit)+'</td><td class="'+(Number(x.debit||0)>Number(x.credit||0)?'fw-loss':'')+'">'+money(Number(x.debit||0)-Number(x.credit||0))+'</td></tr>');
    const history=[...docs.map(d=>({date:d.document_date,title:'سند '+d.document_number,amount:d.total_amount,kind:d.document_type})),...tx.map(t=>({date:t.transaction_date,title:({customer_receipt:'دریافت از شخص',supplier_payment:'پرداخت به تأمین‌کننده',expense_payment:'هزینه',other_income:'درآمد'}[t.transaction_type]||t.transaction_type),amount:t.amount,kind:'تراکنش مالی'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,40).map(x=>'<tr><td>'+dateFa(x.date)+'</td><td>'+esc(x.title)+'</td><td>'+esc(x.kind)+'</td><td>'+money(x.amount)+'</td></tr>');
    shell('<button class="fw-btn secondary" data-action="contacts-back">← بازگشت به دفتر اشخاص</button><section class="fw-hero" style="margin-top:14px"><div><span>پرونده شخص</span><h2>'+esc(c.name)+'</h2><p>'+esc(c.phone||'بدون شماره تماس')+' · '+esc(c.contact_type)+'</p></div><div class="fw-hero-mark">♙</div></section><div class="fw-grid"><section class="fw-card fw-stat"><div><small>تعداد فاکتورهای نهایی</small><strong>'+money(docs.length)+'</strong><em>فاکتور ثبت‌شده</em></div></section><section class="fw-card fw-stat"><div><small>مانده حساب</small><strong class="'+(balance>0?'fw-loss':'')+'">'+money(Math.abs(balance))+'</strong><em>'+(balance>0?'بدهکار':balance<0?'بستانکار':'تسویه')+'</em></div></section><section class="fw-card fw-stat"><div><small>فروش ثبت‌شده</small><strong>'+money(sales)+'</strong><em>ریال</em></div></section><section class="fw-card fw-stat"><div><small>خرید ثبت‌شده</small><strong>'+money(purchases)+'</strong><em>ریال</em></div></section><section class="fw-card fw-stat"><div><small>دریافت از شخص</small><strong>'+money(received)+'</strong><em>ریال</em></div></section><section class="fw-card fw-stat"><div><small>پرداخت به شخص</small><strong>'+money(paid)+'</strong><em>ریال</em></div></section></div><section class="fw-card"><div class="fw-section-head"><div><h2>دفتر کل مشتری</h2><p>گردش بدهکار و بستانکار از دفتر حسابداری مشترک</p></div></div>'+table(ledgerRows,['تاریخ','شرح','بدهکار','بستانکار','مانده گردش'],'ثبت حسابداری برای این شخص وجود ندارد.')+'</section><section class="fw-card"><div class="fw-section-head"><div><h2>گردش و سوابق شخص</h2><p>آخرین اسناد و تراکنش‌های موجود در نسخه وب</p></div></div>'+table(history,['تاریخ','شرح','نوع','مبلغ (ریال)'],'گردشی برای این شخص ثبت نشده است.')+'</section>',
    'پرونده '+esc(c.name),'سوابق مالی و اسناد مرتبط با مشتری یا تأمین‌کننده');
  }
